# owner: platform
from typing import Iterable, List
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _line(row, widths) -> str:
    parts = zip(row, widths)
    return "  ".join(
        text.ljust(size) for text, size in parts
    ).rstrip()


def _check_emails(students: List[Student]) -> None:
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )


def _align(students: List[Student]) -> List[str]:
    cells = [
        (item.display_name, item.section, item.email)
        for item in students
    ]
    sizes = [
        max(len(text) for text in column)
        for column in zip(*cells)
    ]
    return [_line(row, sizes) for row in cells]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    if not ordered:
        raise ProjectError("no students to list")
    _check_emails(ordered)
    return _align(ordered)
